import os

TEST_KUBE_CONFIG = {
    'current-context': 'tls-server-name',
    'contexts': [
        {'name': 'tls-server-name', 'context': {'cluster': 'tls-server-name', 'user': 'ssl'}}
    ],
    'clusters': [
        {'name': 'tls-server-name', 'cluster': {
            'server': 'https://test-host',
            'certificate-authority-data': 'Y2VydHM=',
            'insecure-skip-tls-verify': False,
            'tls-server-name': 'kubernetes.io'
        }}
    ],
    'users': [
        {'name': 'ssl', 'user': {}}
    ]
}

expected = FakeConfig(
    host=TEST_SSL_HOST,
    token=BEARER_TOKEN_FORMAT % TEST_DATA_BASE64,
    cert_file=None,
    key_file=None,
    ssl_ca_cert=None,
    verify_ssl=True,
    tls_server_name=TEST_TLS_SERVER_NAME
)
