loader.load_and_set(actual)

# Compare
match = True
for k in expected.__dict__:
    if k in actual.__dict__:
        ev, av = expected.__dict__[k], actual.__dict__[k]
        if k in FakeConfig.FILE_KEYS:
            if ev is None or av is None:
                if ev != av:
                    print(f'{k}: mismatch (one is None, other is {av!r})')
                    match = False
            else:
                try:
                    with open(ev) as f1, open(av) as f2:
                        if f1.read() != f2.read():
